INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which of the following is a CHEMICAL change?', 'Dissolving sugar in water', 'Melting ice cream', 'Cutting paper', 'Rotting of tomatoes', 'D', 'Rotting forms new substances; others only change appearance.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which shows ONLY a PHYSICAL change?', 'Crushing chunks of ice', 'Rusting of iron', 'Burning wood', 'Milk turning sour', 'A', 'Ice is still water; no new substance formed.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What is the MAIN difference between chemical and physical change?', 'Physical change cannot be reversed', 'Physical change always releases heat', 'Chemical change produces a NEW substance', 'Chemical change is always faster', 'C', 'Composition changes in chemical change; stays the same in physical.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which of these is a CHEMICAL change?', 'Opening a soda can', 'Photosynthesis in plants', 'Painting wood', 'Bending metal', 'B', 'Plants turn CO₂ and water into glucose and oxygen.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Bubbles forming when vinegar is mixed with baking soda is evidence of:', 'Evolution of gas', 'Color change', 'Physical change only', 'Precipitate formation', 'A', 'Bubbles indicate CO₂ gas is released.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Curdling of milk into lumpy solids is an example of which evidence?', 'Temperature drop only', 'Gas evolution', 'Production of light', 'Formation of a precipitate', 'D', 'A precipitate is an insoluble solid formed during a reaction.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Mixing quicklime and water makes the container feel hot. What evidence is this?', 'Color change', 'Change in temperature', 'Gas formation', 'Precipitate formation', 'B', 'Heat released indicates an exothermic chemical reaction.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which is NOT evidence that a chemical reaction occurred?', 'Production of light (like burning)', 'Formation of gas bubbles', 'Change in shape only by cutting', 'Change in color', 'C', 'Cutting changes only the shape, not the substance.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'A student mixes two clear liquids and a yellow solid settles at the bottom. This is:', 'Precipitate formation', 'Physical change', 'Gas evolution', 'Boiling', 'A', 'Formation of a solid from two liquids is a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'In a chemical equation, substances on the LEFT side of the arrow are called:', 'Coefficients', 'Products', 'Precipitates', 'Reactants', 'D', 'Reactants are the starting substances.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Substances written on the RIGHT side of the arrow are:', 'Symbols only', 'Products', 'Reactants', 'Gases always', 'B', 'Products are the new substances formed.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What does the symbol (aq) mean in a chemical equation?', 'Solid precipitate', 'Gaseous state', 'Dissolved in water (aqueous)', 'Liquid pure substance', 'C', 'Aqueous means dissolved in water.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The symbol Δ written above the arrow means:', 'Heat is supplied to the reaction', 'Gas is released', 'A precipitate forms', 'Reaction is reversible', 'A', 'Δ indicates heat is added.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The downward arrow (↓) next to a product means:', 'Heat released', 'Gas evolved', 'Liquid product', 'A solid precipitate was formed', 'D', 'The downward arrow indicates a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What does the + sign between reactants mean?', 'Heat is added', 'Substances are mixed / added together', '"Yields" or "produces"', 'Only one reacts', 'B', 'The plus sign means "reacts with" or "and."', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'A + B → AB is:', 'Single displacement', 'Combustion', 'Combination / Synthesis', 'Decomposition', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AB → A + B is:', 'Combination', 'Double displacement', 'Neutralization', 'Decomposition', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Hydrocarbon + O₂ → CO₂ + H₂O + heat is:', 'Combustion', 'Acid base', 'Precipitation', 'Decomposition', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Acid + Base → Salt + Water is:', 'Decomposition', 'Single replacement', 'Neutralization (special double displacement)', 'Combustion', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AB + C → AC + B is:', 'Synthesis', 'Decomposition', 'Single Displacement / Replacement', 'Double displacement', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'AB + CD → AD + CB is:', 'Combination', 'Double Displacement / Replacement', 'Combustion', 'Single displacement', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', '2Na + Cl₂ → 2NaCl is:', 'Combustion', 'Single displacement', 'Combination', 'Decomposition', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'CaCO₃ → CaO + CO₂ is:', 'Acid base', 'Combination', 'Double displacement', 'Decomposition', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Plants build glucose from CO₂ + H₂O using sunlight. This is:', 'Corrosion', 'Photosynthesis (combination / endothermic)', 'Respiration', 'Combustion', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Glucose + O₂ → CO₂ + H₂O + energy in body cells is:', 'Cellular Respiration (exothermic)', 'Photosynthesis', 'Decomposition', 'Combustion only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Which reaction involves one reactant breaking down into many?', 'Neutralization', 'Single replacement', 'Decomposition', 'Synthesis', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Rusting of iron is an example of:', 'Photosynthesis', 'Neutralization', 'Combustion', 'Oxidation / Corrosion', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Precipitation reactions form:', 'Insoluble solid', 'Gas only', 'Water only', 'No new substance', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'In a single displacement reaction:', 'All substances combine', 'One element swaps place with another', 'One compound splits', 'Nothing changes', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'pre_test', 'Photosynthesis is the reverse of:', 'Acid rain', 'Combustion', 'Respiration', 'Decomposition', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Zn + 2HCl → ZnCl₂ + H₂↑ is:', 'Combination', 'Decomposition', 'Double displacement', 'Single displacement (metal replaces H in acid)', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'AgNO₃ + NaCl → AgCl↓ + NaNO₃ is:', 'Combustion', 'Synthesis', 'Double displacement + precipitation', 'Single displacement', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'CH₄ + 2O₂ → CO₂ + 2H₂O + heat is:', 'Neutralization', 'Decomposition', 'Photosynthesis', 'Combustion of methane (natural gas)', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'SO₂ + NOₓ from vehicles + rain →', 'Ozone', 'Freshwater', 'Acid rain', 'Neutral water', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', '4Fe + 3O₂ + H₂O → 2Fe₂O₃·H₂O (rust) is called:', 'Corrosion / slow oxidation', 'Combustion', 'Neutralization', 'Single displacement', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which reaction is OPPOSITE of photosynthesis?', 'Neutralization', 'Corrosion', 'Acid rain', 'Cellular respiration', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Limestone statues dissolve in acid rain via:', 'Photosynthesis', 'Acid Carbonate double displacement', 'Combustion', 'Synthesis', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Burning gasoline, forests, volcanoes all add what to atmosphere?', 'Water only', 'Nitrogen only', 'CO₂ (greenhouse gas) + acid rain gases', 'Oxygen', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'How does photosynthesis help fight global warming?', 'Makes acid rain', 'Produces heat', 'Releases CO₂', 'Absorbs / removes CO₂; releases O₂', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'A reaction has only ONE reactant. It MUST be:', 'Single displacement', 'Decomposition', 'Combination', 'Combustion', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Burning magnesium ribbon: 2Mg + O₂ → 2MgO is:', 'Neutralization', 'Combination + oxidation', 'Double displacement', 'Decomposition', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which reaction type always produces heat?', 'Electrolysis', 'Melting', 'Combustion', 'Photosynthesis', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', '2H₂O → 2H₂↑ + O₂↑ (with electricity) is:', 'Combustion', 'Single displacement', 'Combination', 'Electrolytic Decomposition', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Fe + CuSO₄ → FeSO₄ + Cu. Why does Fe replace Cu?', 'Cu more active', 'Random', 'Fe is MORE reactive (activity series rule)', 'Fe is lighter', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which environmental reaction is BOTH combination AND exothermic?', 'Corrosion only', 'Electrolysis', 'Formation of acid rain gases in atmosphere', 'Photosynthesis', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Acid rain reacting with steel bridges is which type?', 'Decomposition', 'Single displacement (acid + metal)', 'Combustion', 'Precipitation', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'A reaction has O₂ as reactant AND releases heat. It is almost always:', 'Combustion', 'Neutralization', 'Decomposition', 'Precipitation', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'Which correctly classifies respiration?', 'Single replacement', 'Endothermic decomposition', 'Exothermic combustion-like oxidation', 'Endothermic combination', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'The main environmental impact of uncontrolled combustion is:', 'Only corrosion', 'Global warming + acid rain + air pollution', 'Ozone layer only', 'Only photosynthesis increase', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000102', 1, 'post_test', 'CaCO₃ (coral/shells) + ocean acidification causes:', 'Respiration decrease', 'Coral growth', 'Photosynthesis', 'Double displacement dissolving coral skeletons', 'D', 'This version avoids the repetitive "B" pattern by distributing the correct answers across A, B, C, and D while keeping the', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which is a property of ALL acids?', 'Bitter taste', 'Soapy feel', 'pH > 7', 'Sour taste; turns blue litmus RED', 'D', 'Classic acid property (vinegar, calamansi).', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Bases turn red litmus paper:', 'Yellow', 'Blue', 'Colorless', 'Red', 'B', 'Mnemonic: Base turns Red litmus Blue.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Pure water at 25°C has pH:', '14', '5', '7', '0', 'C', 'pH 7 is neutral.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Phenolphthalein is colorless in acid and ______ in base.', 'Green', 'Yellow', 'Bright pink', 'Red', 'C', 'Standard indicator rule.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which ion do acids release in water?', 'Cl⁻', 'Na⁺', 'OH⁻', 'H⁺ / H₃O⁺', 'D', 'Arrhenius definition of an acid.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Bases release which ion in water?', 'O²⁻', 'OH⁻ (hydroxide)', 'H₃O⁺', 'H⁺', 'B', 'Arrhenius definition of a base.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Common table salt (saline solution) is chemically:', 'NaOH', 'KCl', 'NaCl', 'HCl', 'C', 'Sodium chloride is a neutral salt.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Hydrochloric acid found in the stomach has formula:', 'CH₃COOH', 'HCl', 'H₂SO₄', 'HNO₃', 'B', 'HCl is gastric acid.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Sodium hydroxide, a common strong base (lye), has formula:', 'NH₄OH', 'NaCl', 'NaOH', 'Ca(OH)₂', 'C', 'NaOH is caustic soda.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Methyl orange is ____ in acid and ____ in base.', 'Blue / Red', 'Red / Yellow', 'Yellow / Red', 'Pink / Colorless', 'B', 'Standard synthetic indicator.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which is a natural indicator?', 'Litmus paper only', 'Turmeric', 'Phenolphthalein', 'Methyl orange', 'B', 'Turmeric, red cabbage, and onion are natural indicators.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'A solution with pH 7 is:', 'Basic', 'Strongly acidic', 'Neutral', 'Acidic', 'C', 'Equal H⁺ and OH⁻ concentration.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which acid is found in vinegar?', 'Sulfuric acid', 'Acetic acid', 'Citric acid', 'HCl', 'B', 'Acetic acid gives vinegar its sour taste.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'Which base is found in antacids like milk of magnesia?', 'NaOH', 'NH₄OH', 'KOH', 'Mg(OH)₂', 'D', 'Neutralizes excess stomach acid.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'pre_test', 'When blue litmus paper is placed in a base, it stays:', 'Green', 'Blue', 'Colorless', 'Red', 'B', 'Blue litmus remains blue in a base.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which set are ALL ACIDS?', 'Soap, detergent, antacid', 'NaOH, KOH, Ca(OH)₂', 'HCl, vinegar, calamansi juice', 'NaCl, baking soda, bleach', 'C', 'All are acids.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which set are ALL BASES?', 'Salt, sugar, water', 'NaOH, bleach, milk of magnesia', 'Vinegar, lemon, soda', 'HCl, HNO₃, H₂SO₄', 'B', 'All are bases.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Antacids (Kremil-S) fight hyperacidity because they are:', 'Neutral salts', 'Strong acids', 'Indicators', 'Weak bases', 'D', 'Mild bases neutralize stomach acid.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'A solution with pH = 4 is:', 'Neutral', 'Strongly acidic', 'Weak base', 'Weak acid', 'B', 'Lower pH means stronger acidity.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'pH = 11 is classified as:', 'Neutral', 'Acidic', 'Strongly basic / alkaline', 'Weakly acidic', 'C', 'High pH indicates a strong base.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which pH is the WEAKEST acid?', 'pH 8', 'pH 3', 'pH 6', 'pH 1', 'C', 'Closest to 7 on the acidic side.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Acid + Base → Salt + Water. This reaction is:', 'Combination', 'Decomposition', 'Neutralization', 'Combustion', 'C', 'Neutralization cancels acidic and basic properties.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Turmeric stain turns reddish-brown when soap is applied because soap is:', 'Basic', 'Neutral', 'Acidic', 'A salt', 'A', 'Turmeric turns reddish-brown in a base.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Onion and vanilla change SMELL in acids/bases. They are:', 'Catalysts', 'Olfactory indicators', 'Synthetic indicators', 'Natural color indicators', 'B', 'They indicate acidity/basicity through smell.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Tooth decay starts when mouth pH:', 'Equals 7', 'Is exactly 9', 'Drops below 5.5', 'Rises above 8', 'C', 'Enamel begins dissolving below pH 5.5.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which salt is basic when dissolved in water?', 'NH₄Cl', 'KNO₃', 'NaCl', 'Na₂CO₃', 'D', 'Sodium carbonate forms a basic solution.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which salt is acidic when dissolved in water?', 'KCl', 'NH₄Cl', 'CH₃COONa', 'Na₂SO₄', 'B', 'Ammonium chloride forms an acidic solution.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Dry HCl gas does NOT change dry blue litmus. Why?', 'Litmus only works in bases', 'Dry HCl is a base', 'HCl is not an acid', 'No water → no free H⁺ ions', 'D', 'Water is needed for HCl to ionize.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Each pH unit = ______ change in H⁺ concentration.', '100×', '10×', '5×', '2×', 'B', 'The pH scale is logarithmic.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Arrange STRONGEST ACID → STRONGEST BASE: pH 2, pH 12, pH 6, pH 7, pH 9.', '12 → 9 → 7 → 6 → 2', '2 → 7 → 6 → 9 → 12', '2 → 6 → 7 → 9 → 12', '7 → 2 → 6 → 9 → 12', 'C', 'Lowest pH is the strongest acid.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which salt comes from a strong acid + strong base (neutral pH ≈ 7)?', 'Sodium carbonate', 'Sodium chloride (NaCl)', 'Ammonium chloride', 'Sodium acetate', 'B', 'HCl + NaOH → NaCl + H₂O.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Acidic/basic solutions conduct electricity because they have:', 'Neutral molecules', 'Metal atoms', 'Mobile ions', 'Free electrons', 'C', 'Ions carry electric current.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'When diluting concentrated acid in the lab, ALWAYS:', 'Heat first', 'Pour acid SLOWLY into water with stirring', 'Pour water into acid', 'Mix fast in any order', 'B', 'This prevents dangerous splashing.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Which is a WEAK acid found in vinegar?', 'H₂SO₄', 'HCl', 'CH₃COOH (acetic acid)', 'HNO₃', 'C', 'Acetic acid is the acid in vinegar.', true),
('b0000000-0000-0000-0000-000000000103', 1, 'post_test', 'Baking soda (NaHCO₃) reacts with acids to release:', 'O₂', 'N₂', 'CO₂ gas', 'H₂', 'C', 'Acid + bicarbonate → salt + H₂O + CO₂.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which general equation represents COMBINATION (Synthesis)?', 'AB + CD → AD + CB', 'A + B → AB', 'AB → A + B', 'AB + C → AC + B', 'B', 'Two or more reactants form ONE product.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', '2Na + Cl₂ → 2NaCl is an example of:', 'Single displacement', 'Combustion', 'Decomposition', 'Combination', 'D', 'Na + Cl combine to make one product, NaCl.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'The reaction CaCO₃ → CaO + CO₂ is classified as:', 'Combination', 'Double displacement', 'Decomposition', 'Acid-base reaction', 'C', 'One reactant breaks down into two simpler substances.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What is the general form of DECOMPOSITION?', 'AB + C → AC + B', 'Acid + Base → Salt + Water', 'A + B → AB', 'AB → A + B', 'D', 'Opposite of combination; one becomes two or more substances.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Pb + FeSO₄ → PbSO₄ + Fe is which type?', 'Single displacement', 'Double displacement', 'Combustion', 'Decomposition', 'A', 'Pb replaces Fe in the compound.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In SINGLE DISPLACEMENT, what happens?', 'Ions of two compounds swap', 'One element replaces another element in a compound', 'One compound splits into two', 'Oxygen reacts with a hydrocarbon', 'B', 'General form: AB + C → AC + B.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'AgNO₃ + NaCl → AgCl↓ + NaNO₃ is:', 'Decomposition', 'Combination', 'Double displacement', 'Single displacement', 'C', 'Ag⁺ and Na⁺ exchange partners.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which is ALWAYS a reactant in COMBUSTION reactions?', 'Water', 'Nitrogen', 'Carbon dioxide', 'Oxygen gas (O₂)', 'D', 'Combustion always requires oxygen.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Combustion of a hydrocarbon always produces these two products:', 'Carbon dioxide (CO₂) and Water (H₂O)', 'Oxygen and hydrogen', 'Salt and water', 'Metal oxide and gas', 'A', 'Hydrocarbon + O₂ → CO₂ + H₂O.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'HBr + NaOH → NaBr + H₂O is an example of:', 'Combustion', 'Acid-Base / Neutralization', 'Decomposition', 'Single displacement', 'B', 'Acid + Base → Salt + Water.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Neutralization is a special type of:', 'Decomposition', 'Combination', 'Combustion', 'Double displacement', 'D', 'H⁺ from the acid and the metal from the base exchange places.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which change is reversible and only alters form?', 'Digesting food', 'Tarnishing silver', 'Melting wax', 'Burning wood', 'C', 'Melting is a physical change.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which observation does NOT suggest a chemical change?', 'Permanent color change', 'Light and heat given off', 'Salt dissolving in water', 'New solid not easily separated', 'C', 'Dissolving salt is a physical change.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In the equation Mg + O₂ → MgO, what is magnesium oxide?', 'Catalyst', 'Product', 'Gas', 'Reactant', 'B', 'It is on the right side of the arrow.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which reaction type is: Fuel + O₂ → CO₂ + H₂O?', 'Decomposition', 'Synthesis', 'Single displacement', 'Combustion', 'D', 'Burning a fuel in oxygen is combustion.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What does the arrow (→) mean in a chemical equation?', 'Reacts with', 'Yields / produces', 'Dissolves in', 'Equals', 'B', 'The arrow separates reactants from products.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which is a decomposition reaction?', 'Zn + 2HCl → ZnCl₂ + H₂', '2H₂ + O₂ → 2H₂O', '2H₂O₂ → 2H₂O + O₂', 'NaOH + HCl → NaCl + H₂O', 'C', 'One reactant breaks into two products.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'A reaction where two compounds exchange ions is called:', 'Double displacement', 'Single displacement', 'Decomposition', 'Synthesis', 'A', 'The ions swap partners.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which is an example of synthesis?', 'Sodium chloride + Silver nitrate → Silver chloride + Sodium nitrate', 'Water → Hydrogen + Oxygen', 'Iron + Sulfur → Iron sulfide', 'Wood + Oxygen → Ash + CO₂', 'C', 'Two elements combine to form one compound.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which symbol shows a gaseous product?', '(l)', '(aq)', '(s)', '(g) or ↑', 'D', '(g) or an upward arrow indicates a gas.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Left side of the arrow (→) contains:', 'Products', 'Reactants', 'Coefficients', 'Catalysts', 'B', 'Starting materials you put in.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Right side of the arrow contains:', 'Reactants', 'Products', 'Subscripts', 'Heat', 'B', 'New substances formed.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', '(aq) in equations means:', 'Gas', 'Pure liquid', 'Aqueous / dissolved in water', 'Solid', 'C', 'From Latin aqua = water.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', '(s) means:', 'Gas', 'Solid', 'Solution', 'Catalyst', 'B', 'Solid state of matter.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', '(g) means:', 'Gas', 'Liquid', 'Aqueous', 'Precipitate', 'A', 'Gaseous state.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'The arrow → is read as:', 'equals', 'yields / produces / forms', 'plus', 'reacts with', 'B', 'Standard chemical equation terminology.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Balanced equations have ______ atoms of each element on both sides.', 'different', 'equal', 'increasing', 'random', 'B', 'Required by conservation of mass.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Word equation: Hydrogen + Oxygen → Water. Formula version:', 'H + O → HO', '2H₂ + O₂ → 2H₂O', 'H₂ + O → H₂O', 'H₂O → H₂ + O₂', 'B', 'Correct formulas + balanced.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Symbol (l) stands for:', 'Solid', 'Liquid', 'Gas', 'Dissolved', 'B', 'Pure liquid state.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'A coefficient tells you:', 'Number of atoms in a molecule', 'Number of molecules / moles of substance', 'Charge of the ion', 'Type of reaction', 'B', 'Multiplies every atom in that formula.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'A subscript tells you:', 'Number of molecules', 'Number of that specific atom in one molecule', 'Mass of the substance', 'Speed of reaction', 'B', 'H₂O = 2 H, 1 O per molecule.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'Which is the correct formula for carbon dioxide?', 'CO', 'CO₂', 'C₂O', 'CO₃', 'B', 'One carbon, two oxygen atoms.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'In CaCl₂, the subscript “2” refers to:', 'Calcium atoms', 'Chlorine atoms', 'Total molecules', 'Charge', 'B', 'Two chlorine atoms bonded to one calcium.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'When balancing, you may ONLY change:', 'Subscripts', 'Coefficients (big front numbers)', 'Formulas', 'Element symbols', 'B', 'Changing subscripts changes the substance itself!', true),
('b0000000-0000-0000-0000-000000000104', 1, 'pre_test', 'In 3 H₂O, “3” is a ______; small “2” is a ______.', 'subscript / coefficient', 'coefficient / subscript', 'reactant / product', 'symbol / formula', 'B', 'Coefficient × subscript = total atoms.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which is already BALANCED?', 'H₂ + O₂ → H₂O', 'Ca + Cl₂ → CaCl₂', 'Na + Cl₂ → NaCl', 'Fe + O₂ → Fe₂O₃', 'B', '1 Ca, 2 Cl each side.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In 2 H₂SO₄, total H atoms = ?', '2', '4', '6', '8', 'B', '2 × 2 = 4 H atoms total.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In 4 Al₂O₃, total O atoms = ?', '3', '7', '12', '8', 'C', '4 × 3 = 12 O atoms.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In Mg + 2HCl → MgCl₂ + H₂, how many Cl on product side?', '1', '2', '3', '4', 'B', 'Subscript 2 on Cl in MgCl₂.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'First step in balancing any equation:', 'Add coefficients randomly', 'Change subscripts', 'Count atoms of each element on BOTH sides', 'Add water', 'C', 'Know what you have before adjusting.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Why must equations be balanced?', 'Teacher rule', 'To obey Law of Conservation of Mass', 'To look nice', 'To speed reaction', 'B', 'Atoms are never created/destroyed.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Open beaker releases gas; measured mass drops. Conservation law?', 'Broken', 'Still holds — gas escaped; total mass of all matter unchanged', 'Only applies in labs', 'Atoms destroyed', 'B', 'Closed system = same mass; open = gas escapes measurement.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'N₂ + H₂ → NH₃. Which atoms are unbalanced?', 'Only N', 'Only H', 'Both N and H', 'Both balanced', 'C', '2N→1N; 2H→3H.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In 5C₆H₁₂O₆, total C atoms = ?', '6', '12', '30', '5', 'C', '5 × 6 = 30 carbon atoms.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which action is FORBIDDEN when balancing?', 'Adding coefficients', 'Changing subscripts', 'Counting atoms', 'Writing formulas', 'B', 'Alters the identity of the compound.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ H₂ + __ O₂ → __ H₂O', '1,1,2', '2, 1, 2', '2,2,2', '1,2,1', 'B', '4H + 2O each side.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ N₂ + __ H₂ → __ NH₃', '1,2,2', '1,3,3', '1, 3, 2', '2,3,2', 'C', '2N, 6H each side.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ Al + __ O₂ → __ Al₂O₃', '2,3,1', '2,1,2', '4, 3, 2', '3,4,2', 'C', '4Al, 6O each side.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Balance: __ Fe + __ H₂O → __ Fe₃O₄ + __ H₂', '1,1,1,1', '3, 4, 1, 4', '2,3,1,2', '3,2,1,2', 'B', '3Fe, 8H, 4O each side.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'In balanced 2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O, total O atoms LEFT?', '7', '14', '8', '6', 'B', '7 × 2 = 14 O in 7O₂.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'If 12g C reacts completely with 32g O₂, mass of CO₂ formed = ?', '12g', '32g', '44g', '20g', 'C', '12 + 32 = 44g; conservation of mass.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What is the BEST explanation for balanced equations?', 'Atoms multiply', 'Atoms are rearranged; same number before and after', 'New atoms form', 'Atoms become smaller', 'B', 'Core meaning of conservation of mass.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Never change subscripts because:', 'It makes numbers bigger', 'It changes the identity of the substance', 'It violates charge', 'Coefficients are easier', 'B', 'H₂O vs H₂O₂ = completely different chemicals.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'In a chemical equation, what do we call the substances that are present BEFORE the reaction takes place?', 'Catalysts', 'Products', 'Reactants', 'Precipitates', 'C', 'Reactants are the starting materials; they appear on the left side of the arrow.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'Where are the PRODUCTS of a chemical reaction written in an equation?', 'Above the arrow', 'Left side of the arrow', 'Right side of the arrow', 'Below the arrow', 'C', 'Products are the new substances formed; they appear after the reaction arrow.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What does the symbol "→" mean when used in a chemical equation?', 'Dissolves in', 'Reacts to form', 'Mixes with', 'Equals', 'B', 'It shows the direction of the chemical change from reactants to products.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'Which symbol indicates that a substance is a SOLID in a chemical equation?', '(g)', '(aq)', '(l)', '(s)', 'D', 'State symbols tell the physical form of each substance; (s) = solid.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'The symbol (aq) next to a substance means:', 'It is dissolved in water', 'It is a gas', 'It is a solid powder', 'It is pure liquid water', 'A', '"Aqueous" means dissolved in water to form a solution.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A number written IN FRONT of a chemical formula (e.g., "2 H₂O") is called a:', 'Charge', 'Superscript', 'Coefficient', 'Subscript', 'C', 'Coefficients show how many molecules or formula units take part in the reaction.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A small number written AFTER an element symbol (e.g., "O₂") is called a:', 'Mass number', 'Coefficient', 'Yield', 'Subscript', 'D', 'Subscripts show how many atoms of that element are in one molecule or formula unit.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What does the law of conservation of mass state about chemical reactions?', 'Total mass increases when new substances form', 'Mass changes depending on temperature', 'Total mass of reactants equals total mass of products', 'Total mass decreases when bonds break', 'C', 'Atoms are only rearranged; no atoms are created or destroyed.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction where two or more substances combine to make ONE new substance is called:', 'Double displacement', 'Single displacement', 'Combination / Synthesis', 'Decomposition', 'C', 'General form: A + B → AB.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction where ONE reactant breaks apart into two or more simpler substances is:', 'Combustion', 'Decomposition', 'Replacement', 'Synthesis', 'B', 'General form: AB → A + B.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'What is a CATALYST?', 'A gas always produced', 'A product formed at the end', 'A substance used up during the reaction', 'A substance that speeds up a reaction without being changed or used up', 'D', 'Catalysts are often written above the reaction arrow.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction that releases heat or light energy to the surroundings is called:', 'Exothermic', 'Thermal', 'Endothermic', 'Isothermic', 'A', 'Energy comes OUT of the reaction.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'A reaction that ABSORBS energy from its surroundings (feels cold) is:', 'Combustion', 'Endothermic', 'Displacement', 'Exothermic', 'B', 'Energy goes INTO the reaction.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'In a single displacement reaction:', 'One element replaces another element in a compound', 'Nothing changes partners', 'One compound breaks into elements', 'Two compounds swap partners', 'A', 'General form: A + BC → AC + B.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'pre_test', 'In a double displacement reaction:', 'A fuel reacts with oxygen', 'One element replaces another', 'Two compounds exchange ions to form new compounds', 'Two elements combine', 'C', 'General form: AB + CD → AD + CB.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Combustion reactions always have which reactant?', 'Water', 'Nitrogen', 'Oxygen gas (O₂)', 'Carbon dioxide', 'C', 'Combustion = substance + oxygen → oxides + energy.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'A chemical equation is the best way to represent:', 'Only phase changes like melting', 'A chemical change where new substances form', 'Only physical mixing', 'Just a drawing of atoms', 'B', 'It summarizes exactly what reacts, what forms, and their amounts and states.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'If you see a symbol "Δ" written above the reaction arrow, it means:', 'Electricity is used', 'A catalyst is present', 'Heat is applied', 'Light is needed', 'C', 'Delta (Δ) is the standard symbol for heating.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which of the following is an example of a CHEMICAL change represented by an equation?', 'Sugar dissolving in tea', 'Cutting wood into pieces', 'Iron turning into rust', 'Ice melting to water', 'C', 'Rust is a new substance; the others are only physical changes.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What is the main difference between a WORD EQUATION and a CHEMICAL EQUATION?', 'There is no difference', 'Chemical equations are always longer', 'Word equations show mass conservation; chemical equations do not', 'Word equations use only element names; chemical equations use formulas and symbols', 'D', 'Example: "Hydrogen + Oxygen → Water" (word) vs. "2 H₂ + O₂ → 2 H₂O" (chemical).', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'When an insoluble solid forms and settles out of a solution during reaction, it is called a:', 'Product gas', 'Solvent', 'Solute', 'Precipitate', 'D', 'Often marked (s) or "↓" in equations.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which statement about subscripts is TRUE?', 'They only matter for balancing', 'You can change them to make an equation "look right"', 'They are part of the chemical identity of a substance', 'They count how many reactions happen', 'C', 'Changing a subscript changes the compound itself (e.g., H₂O vs. H₂O₂).', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'In a chemical equation, coefficients apply to:', 'Only the last element', 'The entire formula they stand before', 'Only the first element in the formula', 'Nothing—they are just for counting', 'B', '"2 NaCl" means two whole units of sodium chloride, not two sodium atoms.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'What information is NOT directly given in a typical chemical equation?', 'Exact speed of the reaction', 'Which substances are reactants and products', 'Physical states of each substance', 'Direction of the reaction', 'A', 'Equations show what happens, not how fast it happens.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'A reversible reaction (one that can go forward and backward) uses which symbol?', '↓', '→', '⇌', '=', 'C', 'Reactants form products, and products can reform reactants.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'When balancing is NOT the focus, what does a chemical equation show clearly?', 'The exact cost of chemicals', 'Only the total mass', 'The identity of reactants, products, and reaction type', 'How dangerous it is', 'C', 'Even unbalanced, it tells you what goes in, what comes out, and what kind of change occurs.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which is TRUE about the arrow in a chemical equation?', 'It separates reactants from products and shows direction of change', 'It means "is equal to"', 'It only appears in big reactions', 'It means "can never reverse"', 'A', 'It marks the boundary between starting materials and new substances.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'If you see (g) next to a product, it means:', 'It is hot', 'It dissolves in water', 'A gas is produced', 'A solid is formed', 'C', 'Common example: CO₂(g) or H₂(g).', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Why do we use chemical formulas instead of full names in equations?', 'Only for scientists', 'To make it harder to read', 'To show exactly which atoms and how many are present', 'To make it shorter', 'C', 'Formulas carry precise information about composition.', true),
('b0000000-0000-0000-0000-000000000105', 1, 'post_test', 'Which best describes the purpose of a chemical equation?', 'To explain safety rules', 'To summarize a chemical reaction in a standard, clear way', 'To show how to balance numbers', 'To list all lab equipment needed', 'B', 'It is the universal language for describing chemical changes.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Higher temperature makes reactions generally:', 'Stop', 'Unaffected', 'Faster', 'Slower', 'C', 'Faster particles = more/harder collisions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Substance that speeds reaction without being consumed:', 'Inhibitor', 'Catalyst', 'Product', 'Reactant', 'B', 'Lowers activation energy; enzymes are biological examples.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Reaction that RELEASES heat (feels hot):', 'Slow', 'Endothermic', 'Needs heating', 'Exothermic', 'D', 'Exo = out; thermic = heat.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Reaction that ABSORBS heat (feels cold):', 'Endothermic', 'Fast always', 'Catalyzed', 'Exothermic', 'A', 'Endo = in; takes heat from surroundings.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Smaller particle size → faster reaction because of larger:', 'Catalyst', 'Temperature', 'Surface area', 'Concentration', 'C', 'More exposed area = more collisions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Fire triangle = fuel + oxygen +:', 'Heat / ignition temperature', 'Water', 'Inhibitor', 'Catalyst', 'A', 'Remove any one → fire stops.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Food stays fresh longer in fridge. Which factor?', 'Catalyst', 'Concentration', 'Surface area', 'Lower temperature slows decay', 'D', '#1 real-life food preservation application.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Substance that SLOWS reactions (food preservatives):', 'Product', 'Reactant', 'Inhibitor', 'Catalyst', 'C', 'Opposite of catalyst; e.g., antioxidants.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Which is exothermic?', 'Burning wood / combustion', 'Melting ice', 'Cooking egg', 'Photosynthesis', 'A', 'Combustion releases large amounts of heat.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Activation energy is:', 'Speed of reaction', 'Energy released', 'Total energy of reactants', 'Minimum energy needed to start reaction', 'D', '"Energy hill" reactants must climb.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Collision theory states reactions happen when particles:', 'Have high mass', 'Are close only', 'Touch lightly', 'Collide with enough energy and correct orientation', 'D', 'Effective collisions cause reaction.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Crushing a solid reactant:', 'Adds catalyst', 'Lowers concentration', 'Increases surface area', 'Lowers temperature', 'C', 'Speeds reaction by exposing more particles.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Which factor does NOT increase rate?', 'Higher concentration', 'Catalyst', 'Larger pieces', 'Higher temperature', 'C', 'Larger pieces = less surface area → slower.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Lowering temperature:', 'Stops all reactions', 'Speeds all reactions', 'Has no effect', 'Slows most reactions', 'D', 'Particles move slower; fewer effective collisions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'pre_test', 'Powdered CaCO₃ reacts FASTER than solid chips with acid because:', 'Catalyst added', 'Higher concentration', 'Higher temperature', 'Greater surface area', 'D', 'Powder exposes far more particles to acid.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Concentrated acid reacts faster than dilute acid. Factor?', 'Surface area', 'Catalyst', 'Higher concentration = more particles = more collisions', 'Temperature', 'C', 'More reactant in the same volume.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Enzymes in your body are examples of:', 'Biological catalysts', 'Products', 'Inhibitors', 'Reactants', 'A', 'Speed digestion, respiration, etc.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Water extinguishes fire mainly by:', 'Adding catalyst', 'Removing fuel', 'Increasing O₂', 'Removing HEAT (cools below ignition temperature)', 'D', 'Also smothers via steam blanket.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Fire blanket extinguishes fire by:', 'Cooling', 'Removing OXYGEN (smothers)', 'Removing fuel', 'Adding inhibitor', 'B', 'Cuts off air supply.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Painting / galvanizing iron prevents rust by:', 'Increasing concentration', 'Adding catalyst', 'Blocking contact with H₂O and O₂', 'Increasing temperature', 'C', 'Removes reactants needed for corrosion.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Which food preservation uses LOW water concentration (osmosis)?', 'Freezing', 'Refrigeration', 'Canning', 'Drying / salting / sugaring', 'D', 'Removes water microbes need for decay reactions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Canning food stops spoilage mainly by:', 'Removing OXYGEN + killing microbes with heat', 'Lowering temperature', 'Increasing surface area', 'Adding catalyst', 'A', 'No O₂ = no aerobic decay reactions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Crushing solid reactant into dust increases rate because:', 'Adds catalyst', 'Increases purity', 'Increases surface area drastically', 'Raises temperature', 'C', 'Same mass, far more exposed particles.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Collision theory says reactions happen when particles:', 'Stop moving', 'Only touch lightly', 'Are far apart', 'Collide with correct orientation AND enough energy', 'D', 'Effective collisions = reaction; others bounce.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Stirring reactants usually:', 'Stops reaction', 'Changes product', 'Speeds reaction', 'Slows reaction', 'C', 'Brings fresh reactants together faster.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Which is endothermic?', 'Neutralization', 'Burning', 'Freezing water', 'Photosynthesis', 'D', 'Needs continuous energy input from sunlight.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Why does higher temperature INCREASE rate so much?', 'Lowers surface area', 'Changes reactants', 'More frequent collisions AND more have energy ≥ activation energy', 'Only more collisions', 'C', 'Energy factor is bigger than frequency.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Catalyst speeds reaction by:', 'Becoming product', 'Lowering required activation energy', 'Increasing temperature', 'Increasing surface area', 'B', 'Makes the "energy hill" easier to climb.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Photosynthesis needs constant sunlight. It is:', 'Very fast', 'Catalyst free', 'Endothermic', 'Exothermic', 'C', 'Continuously absorbs light energy.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Explosions are extremely fast due to:', 'Instant gas release + heat + huge surface contact', 'Inhibitors', 'Low concentration', 'Low temperature', 'A', 'All rate factors maximized at once.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Reaction fast at start, slows, stops. Why?', 'Catalyst disappears', 'Temperature increases', 'Surface area grows', 'Reactants used up → concentration drops to zero', 'D', 'No reactant particles left = no more collisions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'How does a catalyst reduce air pollution in car exhaust?', 'Blocks exhaust', 'Speeds conversion of toxic gases → harmless N₂ + CO₂ + H₂O', 'Burns fuel', 'Cools engine', 'B', 'Catalytic converters = environmental catalyst application.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'Higher O₂ concentration makes fire burn faster. This is which factor?', 'Temperature', 'Catalyst', 'Concentration of reactant (O₂)', 'Surface area', 'C', 'More O₂ molecules = more frequent effective collisions.', true),
('b0000000-0000-0000-0000-000000000106', 1, 'post_test', 'The MAIN factor in corrosion prevention (paint/zinc) is:', 'Eliminate contact between metal and O₂/H₂O', 'Increase concentration', 'Add catalyst', 'Lower temperature', 'A', 'Remove one required reactant → reaction cannot happen.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Homeostasis is best defined as:', 'Constant unchanging state', 'Only temperature control', 'Stable internal balance despite external changes', 'All body reactions stopping', 'C', 'Dynamic balance; conditions fluctuate within a normal range.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which organ system is the MAIN control center for homeostasis?', 'Skeletal system', 'Digestive system', 'Excretory system', 'Nervous + Endocrine systems', 'D', 'Nerves send fast signals; hormones give slower, longer lasting control.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'When body temperature rises, you sweat to cool down. This is:', 'No feedback', 'Negative feedback', 'Positive feedback', 'Stimulus only', 'B', 'Reverses the change back to normal.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'The “normal” or target value in homeostasis is called the:', 'Set point', 'Effector', 'Response', 'Stimulus', 'A', 'E.g., human body temperature set point ≈ 37°C.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which detects changes in the body’s internal or external environment?', 'Control center', 'Response', 'Receptor / Sensor', 'Effector', 'C', 'E.g., nerve endings in skin detect heat/cold.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which part carries out the action to fix the change?', 'Stimulus', 'Effector (muscle / gland)', 'Receptor', 'Control center', 'B', 'Muscles contract; glands release hormones/sweat.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Negative feedback works to:', 'Reverse / correct change back to set point', 'Stop all activity', 'Change the set point permanently', 'Increase change', 'A', 'Most common homeostatic mechanism.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which is NOT maintained by homeostasis?', 'Blood glucose', 'Random constant height', 'Blood pH', 'Body temperature', 'B', 'Height changes with growth; not a regulated balance.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'The control center for temperature regulation is the:', 'Heart', 'Lungs', 'Hypothalamus (brain)', 'Liver', 'C', 'Receives signals and sends commands.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'When you are cold, blood vessels in skin:', 'Burst', 'Constrict / narrow', 'Dilate / widen', 'Disappear', 'B', 'Keeps warm blood inside core → reduces heat loss.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Which system uses chemical messengers called hormones?', 'Digestive', 'Nervous', 'Endocrine', 'Circulatory', 'C', 'Slower but longer lasting control.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Insulin and glucagon regulate:', 'Water balance', 'Blood glucose level', 'Heart rate', 'Body temperature', 'B', 'Work together to keep sugar stable.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'If blood sugar rises, pancreas releases:', 'Thyroxine', 'Adrenaline', 'Insulin', 'Glucagon', 'C', 'Lowers sugar by moving it into cells.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'If blood sugar drops, pancreas releases:', 'Estrogen', 'Insulin', 'Cortisol', 'Glucagon', 'D', 'Releases stored sugar from liver.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'pre_test', 'Kidneys help maintain:', 'Water and salt balance', 'Bone density', 'Muscle strength', 'Body temperature', 'A', 'Adjust urine concentration.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Shivering when cold is an example of:', 'Exothermic reaction only', 'No homeostatic control', 'Negative feedback generating heat', 'Positive feedback increasing heat loss', 'C', 'Muscle movement produces heat to raise body temperature back to the set point.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which is NOT a key homeostatic balance in humans?', 'Water / salt balance', 'Constant body weight forever', 'Blood glucose level', 'Body temperature', 'B', 'Weight changes naturally; it is not a fixed regulated set point.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Insulin lowers blood sugar; glucagon raises it. This is:', 'Positive feedback loop', 'Excretion only', 'Opposing negative feedback', 'Uncontrolled reaction', 'C', 'Two hormones work against each other to keep glucose stable.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Positive feedback differs from negative feedback because it:', 'Has no control center', 'Only works in plants', 'Reverses the change', 'AMPLIFIES / increases the change away from the set point', 'D', 'Rare in the body; e.g., childbirth, blood clotting.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'When blood sugar rises after eating, the pancreas releases:', 'Adrenaline', 'Glucagon', 'Thyroxine', 'Insulin', 'D', 'Insulin helps cells take in glucose; lowers blood sugar.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which organ MAINLY controls water balance and waste removal?', 'Stomach', 'Heart', 'Kidney', 'Lungs', 'C', 'Adjusts urine concentration; keeps salt/water levels stable.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Sweating and vasodilation both help:', 'Raise blood sugar', 'Lower body temperature', 'Lower blood pressure', 'Raise body temperature', 'B', 'Remove excess heat from the body.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which is an example of positive feedback?', 'Insulin action', 'Sweating', 'Blood clotting', 'Breathing rate', 'C', 'More clotting chemicals → faster clotting until sealed.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Homeostasis requires:', 'Constant energy input', 'No energy', 'Only sleep', 'Only food', 'A', 'Active balancing process.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'If homeostasis fails for blood pH, this happens first:', 'Faster breathing', 'More sweating', 'Growth', 'Enzymes stop working / denature', 'D', 'Wrong pH changes protein shape.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'When you exercise, breathing rate increases to balance:', 'Heat in / heat out', 'Water in / salt out', 'O₂ in / CO₂ out', 'Sugar in / fat out', 'C', 'Maintain gas balance in blood.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'The order of a feedback loop is:', 'Control → Stimulus → Receptor → Effector', 'Response → Stimulus → Effector → Control', 'Stimulus → Receptor → Control → Effector → Response', 'Effector → Receptor → Control → Response', 'C', 'Correct sequence for all homeostatic loops.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which is the ONLY example of POSITIVE feedback below?', 'Kidneys saving water when dehydrated', 'Sweating when hot', 'Insulin lowering sugar', 'Oxytocin increasing stronger contractions during birth', 'D', 'More contraction → more hormone → even stronger contraction until birth.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'If homeostasis FAILS for a long time, the result is:', 'Faster growth', 'Permanent set point change', 'Disease / organ damage / death', 'Improved health', 'C', 'Unbalanced conditions damage cells and stop organs working.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which statement about homeostasis is TRUE?', 'Only controls temperature', 'Stops when you sleep', 'Only happens in warm-blooded animals', 'Requires constant energy input', 'D', 'Active process; needs energy to keep balancing levels.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Dehydration causes kidneys to:', 'Reabsorb more water back into blood', 'Release more water', 'Make more urine', 'Stop working', 'A', 'Negative feedback restores water balance.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'When blood pressure rises, body responds to:', 'Stop heart', 'Ignore it', 'Lower it back to normal', 'Raise it more', 'C', 'Negative feedback corrects the change.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Which best describes “dynamic equilibrium”?', 'Rapid wild swings', 'Never changes', 'Always exactly the same', 'Small changes within a healthy range', 'D', 'Homeostasis is stable but flexible.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Diabetes is a disease related to which homeostatic failure?', 'Water balance', 'Blood glucose regulation', 'Salt balance', 'Temperature', 'B', 'Problem with insulin production or use.', true),
('b0000000-0000-0000-0000-000000000107', 1, 'post_test', 'Without homeostasis:', 'No change occurs', 'Growth speeds up', 'Cells and organs cannot function', 'Body works better', 'C', 'Conditions drift outside safe limits → damage or death.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Evolution is BEST defined as:', 'Instant creation of new species', 'Only large animals getting stronger', 'Gradual change in the inherited traits of a POPULATION over many generations', 'Individual organisms changing during their lifetime', 'C', 'Evolution happens to populations, not single individuals; traits are passed across generations.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Who is the scientist who first proposed natural selection as the main mechanism of evolution?', 'Charles Darwin', 'Gregor Mendel', 'Antoine Lavoisier', 'Albert Einstein', 'A', 'Darwin published On the Origin of Species in 1859 based on Galápagos Islands observations.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Natural selection is often summarized as:', 'Traits you acquire during life are passed to offspring', 'Survival and reproduction of organisms BEST FITTED to their environment', 'Only the largest animals survive', 'Strongest always kill the weakest', 'B', '“Fitness” = ability to survive AND produce fertile offspring, not just physical strength.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Any inherited trait that helps an organism survive and reproduce in its environment is called:', 'Adaptation', 'Variation', 'Fossil', 'Isolation', 'A', 'Example: thick fur in polar bears, long neck in giraffes.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'The natural differences in traits between individuals of the same species (e.g., different beak sizes in finches) is called:', 'Selection', 'Heredity', 'Variation', 'Isolation', 'C', 'Variation must already exist in a population for natural selection to act on it.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'For evolution to happen, useful traits must be able to be passed from parents to offspring. This is called:', 'Isolation', 'Variation', 'Adaptation', 'Heredity / Inheritance', 'D', 'Traits only affect evolution if they are genetic and can be inherited.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Preserved remains, traces, or impressions of ancient organisms found in rock layers are called:', 'Endemic species', 'Fossils', 'Adaptations', 'Homologous structures', 'B', 'Examples: bones, shells, footprints, leaf imprints trapped in sedimentary rock.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Body parts of different species that have SIMILAR BONE STRUCTURE but different functions (e.g., human arm, whale flipper, bat wing) are:', 'Vestigial structures', 'Fossils', 'Homologous structures', 'Analogous structures', 'C', 'Same basic plan = inherited from a common ancestor.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'A body part that has lost most or all of its original function through evolution (e.g., human appendix, tailbone) is:', 'Analogous', 'Adaptation', 'Homologous', 'Vestigial structure', 'D', 'It is reduced in size; remains as evidence of an ancestor that used it fully.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'The study of where different species live on Earth and why they are found there is:', 'Genetics', 'Comparative anatomy', 'Paleontology', 'Biogeography', 'D', 'Explains why islands often have unique species found nowhere else.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'The peppered moth in England changed from mostly light to mostly dark during the Industrial Revolution because tree trunks turned black with soot. This is a famous example of:', 'Biogeography', 'Artificial selection', 'Natural selection in action', 'Vestigial formation', 'C', 'Dark moths survived predation by birds better; they reproduced more and became common.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'A river changes course and permanently splits one population of beetles into two groups that never meet again. This is:', 'Natural selection', 'Artificial selection', 'Reproductive isolation', 'Geographic isolation', 'D', 'Physical barrier (river, mountain, ocean) separates populations; first step to forming new species.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Bird wing and insect wing have the SAME FUNCTION (flying) but completely different internal structure. They are:', 'Vestigial structures', 'Homologous structures', 'Fossils', 'Analogous structures', 'D', 'Same job, different origin = evolved independently, NOT from a common flying ancestor.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Why is isolation important in forming NEW species (speciation)?', 'It creates fossils faster', 'It increases mutation rate instantly', 'It stops gene flow between groups, letting them evolve differently over time', 'It makes organisms weaker', 'C', 'Without contact, separated populations accumulate different traits until they can no longer interbreed.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'pre_test', 'Fossils found in DEEPER / older rock layers are generally:', 'Simpler and more different from living species today', 'Only large mammals', 'Identical to modern organisms', 'More complex than modern life', 'A', 'Fossil record clearly shows simple life first, then gradual change to more complex forms over time.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Which is the BEST evolutionary explanation for giraffes'' long necks?', 'Long-necked variants survived better, reproduced more, and passed the trait on', 'A random mutation made all necks long in one generation', 'They stretched to reach high leaves and passed stretched necks to babies', 'All giraffes chose to grow longer necks', 'A', 'Variation existed first; natural selection favored longer necks over many generations.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Farmers choosing only the largest, sweetest mangoes to plant next season is:', 'Geographic isolation', 'Artificial selection', 'Vestigial selection', 'Natural selection', 'B', 'Humans, not nature, select which traits get passed on.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Early embryos of fish, chicken, pig, and human look very similar. This evidence of common ancestry comes from:', 'DNA sequencing only', 'Comparative embryology', 'Fossil record', 'Biogeography', 'B', 'Shared early developmental stages = inherited from a shared vertebrate ancestor.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Two groups of frogs live in the same pond but mate at different months of the year and never interbreed. This is:', 'Geographic isolation', 'Analogous breeding', 'Reproductive isolation', 'Artificial selection', 'C', 'No physical barrier, but differences in behavior/time prevent mating; they are now separate species.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'The Philippine Eagle is found only in the Philippines and nowhere else on Earth. It is called:', 'An endemic species', 'An artificial species', 'A vestigial species', 'A fossil species', 'A', 'Biogeography: islands and isolated countries evolve many unique endemic species.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Which is the CORRECT sequence of events for a new species to form (speciation)?', 'Isolation → New species → Variation → Selection', 'New species → Variation → Isolation → Selection', 'Variation → Geographic Isolation → Natural Selection → Reproductive Isolation → New species', 'Selection → Variation → Isolation → New species', 'C', 'Variation must exist first; separation stops gene flow; selection makes groups different until they can no longer', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Why is natural selection considered the PRIMARY mechanism of evolution, not mutation, genetic drift, or chance alone?', 'It was the first mechanism discovered', 'It is the only mechanism that CONSISTENTLY produces ADAPTATIONS matched to the environment', 'It is the only mechanism that changes traits', 'It works instantly in one generation', 'B', 'Other mechanisms exist, but only natural selection reliably builds useful, environment-matched traits over time.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Modern whales have tiny, unused pelvic (hip) bones buried deep inside their bodies. This vestigial structure is strong evidence that:', 'Whales evolved from fish directly', 'The pelvic bone has always been useless', 'Whales are still evolving legs today', 'Whales evolved from 4-legged land-dwelling mammals that moved back to the sea', 'D', 'Fossil series confirms this: walking whale → semi-aquatic → fully aquatic modern whale.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Someone says: “Evolution is just a theory, so it’s just a guess.” The CORRECT scientific response is:', 'In science, “theory” means a well-tested explanation supported by massive, repeated evidence from many fields', 'Evolution is only a hypothesis', 'Theories become laws once proven; evolution is almost a law', 'True, it has no evidence yet', 'A', 'Scientific theory ≠ casual “guess”; it is the highest, most reliable level of scientific explanation.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Fossils of the same extinct reptile Mesosaurus are found only in eastern South America and western Africa. This, plus matching coastlines, strongly supports:', 'It evolved independently on both continents', 'Continental drift / Pangaea: these continents were once joined together', 'The species swam across the Atlantic Ocean', 'Fossils were carried by humans', 'B', 'Key biogeography evidence: landmasses split and carried their resident species with them.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Which of the following is NOT a required condition for natural selection to occur?', 'Traits acquired during an organism''s life (e.g., bigger muscles from exercise) are passed to offspring', 'Variation exists in the population', 'Traits are heritable', 'More offspring are born than can survive', 'A', 'This was Lamarck''s WRONG idea; only genetic/inherited traits, not acquired ones, are passed on.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Homologous structures (e.g., forelimbs of vertebrates) are strong evidence of common ancestry mainly because:', 'They perform exactly the same function', 'They appear only in fossil species', 'They share the same unique bone arrangement inherited from a shared ancestor, modified for different jobs', 'They look identical externally', 'C', 'Same basic plan, different uses = descent with modification from one ancestor.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'A severe 10-year drought hits an island; all small, soft seeds die, leaving only large, hard seeds. Over generations, what will natural selection do to the island’s finch population?', 'All finches will instantly grow larger beaks in one year', 'Average beak size will become LARGER, thicker, and stronger', 'Average beak size will get smaller and weaker', 'Beak size will not change at all', 'B', 'Birds with larger, stronger beaks survive and reproduce; the trait becomes more common over generations.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'If two separated populations are NOT geographically isolated and individuals keep moving/mating between them:', 'Mutations stop occurring', 'Natural selection cannot happen at all', 'Gene flow continues; they will NOT diverge into separate species', 'They will definitely become separate species', 'C', 'Constant mixing keeps their gene pools similar; isolation is required for populations to split into new species.', true),
('b0000000-0000-0000-0000-000000000108', 1, 'post_test', 'Which combination of evidence gives the STRONGEST , most reliable support for evolution by common descent?', 'Only DNA similarity alone', 'Only embryology alone', 'Fossil record + homologous structures + DNA/protein similarity + biogeography, all agreeing', 'Only fossil record alone', 'C', 'Multiple independent lines of evidence all converging on the same conclusion is what makes evolution one of the', true);
